import { useMemo, useState } from "react";
import { toast } from "sonner";
import { Badge } from "@/components/ui/badge";
import { Button } from "@/components/ui/button";
import { Progress } from "@/components/ui/progress";
import { ArrowDown, ArrowRight, BrainCircuit, Check, ChevronRight, CloudSnow, Compass, FileCheck2, Fuel, Gauge, MapPin, Package, Pause, Play, RefreshCw, Route, ShieldAlert, Snowflake, Users, Wand2, X, Zap } from "lucide-react";

const INITIAL_REQUEST = { destination: "Bharati", duration: 45, personnel: 12, objective: "Climate sampling", capacity: 2000 };
const PLAN_STEPS = [
  { label: "PERSONNEL", value: "12 researchers", detail: "2 field leads · 8 researchers · 2 logistics / safety", icon: Users },
  { label: "CARGO", value: "2,000 kg manifest", detail: "Food 2,160 kg · Fuel 480 L · Medical reserve 94% · Research equipment", icon: Package },
  { label: "ROUTE", value: "Base → Camp Alpha → Bharati", detail: "187 km modeled corridor · weather buffer included", icon: Route },
  { label: "RESOURCE RESERVE", value: "18-day food reserve", detail: "9-day fuel reserve · battery reserve 11 days · heating reserve 6 days", icon: Fuel },
  { label: "RISK CONTROLS", value: "18-hour weather buffer", detail: "Emergency reserve staged at Camp Alpha · radio check at each waypoint", icon: ShieldAlert },
];

export default function AutonomousMissionPlanner() {
  const [request, setRequest] = useState(INITIAL_REQUEST);
  const [plan, setPlan] = useState(null);
  const [replan, setReplan] = useState(null);
  const [planStatus, setPlanStatus] = useState("draft");
  const [selectedControl, setSelectedControl] = useState("weather");
  const controls = useMemo(() => ["weather", "cargo", "personnel", "communication"], []);
  const update = (key, value) => setRequest(current => ({ ...current, [key]: value }));
  const generate = () => {
    const readiness = Math.min(96, Math.max(68, 84 + (Number(request.capacity) >= 2000 ? 2 : -5) + (Number(request.personnel) >= 12 ? 0 : -7) - (Number(request.duration) > 45 ? 4 : 0)));
    setPlan({ readiness, generatedAt: new Date().toLocaleTimeString([], { hour: "2-digit", minute: "2-digit" }) });
    setReplan(null); setPlanStatus("proposed");
    toast.success("Autonomous mission plan generated for command review");
  };
  const runReplan = () => { setReplan({ arrival: "00:30", delay: "8 hours", risk: 31, originalRisk: 42, route: "Route C", fuel: "+12%", medical: "unchanged" }); toast.success("Blizzard response plan recalculated"); };
  const applyReplan = () => { setPlanStatus("replanned"); toast.success("Revised mission plan accepted and activated"); };
  return <div className="p-4 md:p-8 space-y-6">
    <div className="flex items-start justify-between flex-wrap gap-4"><div><div className="text-[10px] font-mono-tel uppercase tracking-[.2em] text-slate-500">Module · 13 / Mission planning</div><h1 className="font-display text-2xl md:text-3xl font-bold text-emerald-100 mt-2">Autonomous Mission Planner</h1><p className="text-sm text-slate-400 mt-1">Give POLAR the mission objective. It constructs a proposed expedition plan for human review instead of waiting for every plan detail to be entered manually.</p></div><Badge variant="outline" className="border-emerald-500/40 text-emerald-300"><Wand2 className="h-3.5 w-3.5 mr-1.5" />Human review required</Badge></div>
    <section className="rounded-2xl border border-emerald-500/25 bg-emerald-500/[.035] p-5 md:p-6"><div className="flex items-start gap-3"><div className="rounded-xl bg-emerald-500/15 p-3"><BrainCircuit className="h-6 w-6 text-emerald-300" /></div><div><div className="text-[10px] font-mono-tel uppercase tracking-[.22em] text-emerald-300">01 · Objective to plan</div><h2 className="font-display text-xl font-bold text-white mt-1">Expedition request</h2><p className="text-xs text-slate-500 mt-1">POLAR uses destination, duration, team size, objective, and cargo capacity to construct the first mission draft.</p></div></div><div className="grid grid-cols-1 md:grid-cols-2 xl:grid-cols-5 gap-3 mt-6"><Field label="Destination" value={request.destination} onChange={value => update("destination", value)} /><Field label="Duration (days)" type="number" value={request.duration} onChange={value => update("duration", Number(value))} /><Field label="Personnel" type="number" value={request.personnel} onChange={value => update("personnel", Number(value))} /><Field label="Research objective" value={request.objective} onChange={value => update("objective", value)} /><Field label="Cargo capacity (kg)" type="number" value={request.capacity} onChange={value => update("capacity", Number(value))} /></div><Button onClick={generate} className="mt-5 bg-emerald-500 hover:bg-emerald-400 text-slate-950"><Wand2 className="h-4 w-4 mr-2" />Generate proposed mission plan</Button></section>
    {plan && <section className="rounded-2xl border border-cyan-500/25 bg-cyan-500/[.03] p-5 md:p-6"><div className="flex items-start justify-between gap-4 flex-wrap"><div><div className="text-[10px] font-mono-tel uppercase tracking-widest text-cyan-300">02 · Proposed mission plan · generated {plan.generatedAt}</div><h2 className="font-display text-xl font-bold mt-1">{request.destination} · {request.duration}-day {request.objective} expedition</h2><p className="text-xs text-slate-500 mt-1">POLAR assembled this plan from mission objective, reserve rules, operational history, and current risk signals.</p></div><Badge variant="outline" className={planStatus === "replanned" ? "border-emerald-500/40 text-emerald-300" : "border-cyan-500/40 text-cyan-300"}>{planStatus === "replanned" ? "ACTIVE · REPLANNED" : "PROPOSED FOR REVIEW"}</Badge></div><div className="grid grid-cols-1 xl:grid-cols-[1fr_.7fr] gap-5 mt-5"><div className="space-y-2">{PLAN_STEPS.map((step, index) => { const Icon = step.icon; return <div key={step.label} className="rounded-xl border border-slate-800 bg-slate-950/60 p-4 flex gap-3"><div className="h-9 w-9 shrink-0 rounded-lg bg-cyan-500/10 grid place-items-center"><Icon className="h-4 w-4 text-cyan-300" /></div><div className="flex-1"><div className="flex items-center gap-2"><div className="text-[10px] font-mono-tel uppercase tracking-widest text-cyan-300">{step.label}</div>{index < 2 && <Badge variant="outline" className="border-emerald-500/30 text-emerald-300 text-[9px]">READY</Badge>}</div><div className="text-sm font-semibold text-slate-100 mt-1">{index === 0 ? `${request.personnel} researchers` : step.value}</div><div className="text-xs text-slate-500 mt-1">{step.detail}</div></div><ChevronRight className="h-4 w-4 text-slate-600 mt-2" /></div>; })}</div><div className="rounded-xl border border-slate-800 bg-slate-950/70 p-5 h-fit"><div className="text-[10px] uppercase tracking-widest text-slate-500">Mission readiness</div><div className="font-mono-tel text-5xl font-bold text-emerald-300 mt-2">{plan.readiness}%</div><Progress value={plan.readiness} className="h-2 mt-4" /><div className="mt-5 space-y-2 text-xs">{[["Personnel assigned", true], ["Cargo capacity sufficient", Number(request.capacity) >= 2000], ["Food / medical reserve", true], ["Fuel reserve", true], ["Weather buffer", true], ["Emergency resources", true]].map(([label, ok]) => <div key={label} className="flex items-center justify-between"><span className="text-slate-400">{label}</span>{ok ? <Check className="h-4 w-4 text-emerald-300" /> : <AlertTriangle className="h-4 w-4 text-amber-300" />}</div>)}</div><div className="mt-5 flex gap-2"><Button onClick={() => { setPlanStatus("accepted"); toast.success("Proposed mission plan accepted"); }} className="flex-1 bg-emerald-500 hover:bg-emerald-400 text-slate-950"><FileCheck2 className="h-4 w-4 mr-2" />Accept plan</Button><Button onClick={() => toast.message("Plan remains in review") } variant="outline" className="border-slate-700 text-slate-300"><Pause className="h-4 w-4" /></Button></div></div></div></section>}
    {plan && <section className="rounded-2xl border border-orange-500/25 bg-orange-500/[.035] p-5 md:p-6"><div className="flex items-start justify-between gap-4 flex-wrap"><div><div className="text-[10px] font-mono-tel uppercase tracking-widest text-orange-300">03 · Continuous operational replanning</div><h2 className="font-display text-xl font-bold mt-1 flex items-center gap-2"><RefreshCw className="h-5 w-5 text-orange-300" />Replan mission</h2><p className="text-xs text-slate-500 mt-1">This is not a what-if simulation. POLAR recalculates the active plan when a live operational change is detected.</p></div><Badge variant="outline" className="border-rose-500/40 text-rose-300"><CloudSnow className="h-3 w-3 mr-1" />BLIZZARD DETECTED</Badge></div><div className="grid grid-cols-1 md:grid-cols-2 gap-3 mt-5">{controls.map(control => <button key={control} onClick={() => setSelectedControl(control)} className={`rounded-lg border p-3 text-left capitalize ${selectedControl === control ? "border-orange-400/50 bg-orange-500/[.08]" : "border-slate-800 bg-slate-950/50"}`}><div className="text-xs font-semibold text-slate-200">{control} disruption</div><div className="text-[10px] text-slate-500 mt-1">Use current telemetry to recalculate the mission</div></button>)}</div><Button onClick={runReplan} className="mt-4 bg-orange-500 hover:bg-orange-400 text-slate-950"><RefreshCw className="h-4 w-4 mr-2" />Calculate revised plan</Button>{replan && <div className="mt-5 rounded-xl border border-orange-500/25 bg-slate-950/70 p-5"><div className="grid grid-cols-1 md:grid-cols-3 gap-5"><PlanColumn title="ORIGINAL PLAN" value="Station B arrival: 16:00" detail="Risk: 42" tone="slate" /><ArrowDown className="md:hidden h-5 w-5 text-orange-300 mx-auto" /><PlanColumn title="BLIZZARD DETECTED" value="Weather window closed" detail="Route exposure increasing" tone="rose" /><ArrowDown className="md:hidden h-5 w-5 text-orange-300 mx-auto" /><PlanColumn title="NEW PLAN" value={`Arrival: ${replan.arrival}`} detail={`Risk: ${replan.risk} · ${replan.route}`} tone="emerald" /></div><div className="grid grid-cols-2 md:grid-cols-4 gap-2 mt-5">{[["Departure", `Delay ${replan.delay}`], ["Route", replan.route], ["Fuel reserve", replan.fuel], ["Medical reserve", replan.medical]].map(([label, value]) => <div key={label} className="rounded-lg border border-slate-800 p-3"><div className="text-[10px] uppercase tracking-widest text-slate-500">{label}</div><div className="font-mono-tel text-sm text-slate-200 mt-1">{value}</div></div>)}</div><div className="mt-5 flex flex-wrap gap-2"><Button onClick={applyReplan} className="bg-emerald-500 hover:bg-emerald-400 text-slate-950"><Check className="h-4 w-4 mr-2" />Accept revised plan</Button><Button onClick={() => { setReplan(null); toast.message("Current plan retained for command review"); }} variant="outline" className="border-slate-700 text-slate-300"><X className="h-4 w-4 mr-2" />Keep current plan</Button></div></div>}</section>}
    <section className="rounded-2xl border border-slate-800 bg-slate-950/60 p-5"><div className="flex items-center gap-2"><Compass className="h-4 w-4 text-cyan-300" /><div><h2 className="font-display text-lg font-bold">Planner guardrails</h2><p className="text-xs text-slate-500 mt-1">Autonomous planning proposes actions; the expedition commander remains the approval point.</p></div></div><div className="grid grid-cols-1 md:grid-cols-3 gap-3 mt-4">{[["Explainable", "Every plan shows cargo, route, reserve, and risk controls."], ["Reversible", "Keep current plan remains available during replanning."], ["Human-led", "POLAR never silently dispatches people or cargo."]].map(([label, detail]) => <div key={label} className="rounded-lg border border-slate-800 p-3"><div className="text-sm font-semibold text-slate-200">{label}</div><div className="text-xs text-slate-500 mt-1">{detail}</div></div>)}</div></section>
  </div>;
}
function Field({ label, value, onChange, type = "text" }) { return <label className="text-[10px] uppercase tracking-widest text-slate-500">{label}<input type={type} value={value} onChange={event => onChange(event.target.value)} className="mt-2 w-full rounded-lg border border-slate-700 bg-slate-950/80 px-3 py-2.5 text-sm normal-case tracking-normal text-slate-100 outline-none focus:border-emerald-400" /></label>; }
function PlanColumn({ title, value, detail, tone }) { const colors = { slate: "border-slate-700", rose: "border-rose-500/40 bg-rose-500/[.04]", emerald: "border-emerald-500/40 bg-emerald-500/[.04]" }; return <div className={`rounded-xl border p-4 ${colors[tone]}`}><div className="text-[10px] uppercase tracking-widest text-slate-500">{title}</div><div className="text-sm font-semibold text-slate-100 mt-2">{value}</div><div className="text-xs text-slate-400 mt-1">{detail}</div></div>; }
