import { useMemo, useState } from "react";
import { toast } from "sonner";
import { Badge } from "@/components/ui/badge";
import { Button } from "@/components/ui/button";
import { Progress } from "@/components/ui/progress";
import { Select, SelectContent, SelectItem, SelectTrigger, SelectValue } from "@/components/ui/select";
import { AlertTriangle, CalendarClock, CheckCircle2, Clock3, Gauge, History, Radio, Search, ShieldCheck, Thermometer, TrendingUp, Wrench, Zap } from "lucide-react";

const INITIAL_ASSETS = [
  { id: "GENERATOR-07", type: "Generator", station: "Bharati Research Station", hours: 1820, lastMaintenance: 41, temp: 68, vibration: 72, risk: 76, priority: "HIGH", recommendation: "Schedule inspection within 48 hours.", nextService: "Immediate" },
  { id: "GENERATOR-03", type: "Generator", station: "Maitri Research Station", hours: 1435, lastMaintenance: 26, temp: 48, vibration: 44, risk: 52, priority: "MODERATE", recommendation: "Inspect coolant loop within 7 days.", nextService: "7 days" },
  { id: "VEHICLE-03", type: "Tracked vehicle", station: "Field Camp Alpha", hours: 1240, lastMaintenance: 18, temp: 39, vibration: 31, risk: 34, priority: "MODERATE", recommendation: "Continue monitoring; service in 12 days.", nextService: "12 days" },
  { id: "RADIO-12", type: "Communications", station: "Maitri Research Station", hours: 860, lastMaintenance: 9, temp: 22, vibration: 18, risk: 18, priority: "LOW", recommendation: "No immediate action. Next check in 30 days.", nextService: "30 days" },
  { id: "PUMP-04", type: "Water pump", station: "Himadri Research Station", hours: 2110, lastMaintenance: 34, temp: 54, vibration: 61, risk: 63, priority: "HIGH", recommendation: "Schedule bearing inspection within 72 hours.", nextService: "72 hours" },
];

const PRIORITY_STYLE = { HIGH: "border-rose-500/50 text-rose-300 bg-rose-500/10", MODERATE: "border-amber-500/50 text-amber-300 bg-amber-500/10", LOW: "border-emerald-500/40 text-emerald-300 bg-emerald-500/10" };

export default function EquipmentMaintenance() {
  const [assets, setAssets] = useState(INITIAL_ASSETS);
  const [station, setStation] = useState("All stations");
  const [priority, setPriority] = useState("All priorities");
  const [query, setQuery] = useState("");
  const [selectedId, setSelectedId] = useState("GENERATOR-07");
  const [showHistory, setShowHistory] = useState(false);
  const stations = ["All stations", ...new Set(INITIAL_ASSETS.map(asset => asset.station))];
  const filtered = useMemo(() => assets.filter(asset => station === "All stations" || asset.station === station).filter(asset => priority === "All priorities" || asset.priority === priority).filter(asset => `${asset.id} ${asset.type} ${asset.station}`.toLowerCase().includes(query.toLowerCase())), [assets, station, priority, query]);
  const selected = assets.find(asset => asset.id === selectedId) || assets[0];
  const averageRisk = Math.round(assets.reduce((sum, asset) => sum + asset.risk, 0) / assets.length);
  const inspection = asset => {
    setAssets(items => items.map(item => item.id === asset.id ? { ...item, risk: Math.max(8, item.risk - 28), priority: "LOW", lastMaintenance: 0, nextService: "30 days", recommendation: "Inspection logged. Next check in 30 days." } : item));
    toast.success(`${asset.id} inspection scheduled and maintenance queue updated`);
  };
  return (
    <div className="p-4 md:p-8 space-y-6">
      <div className="flex items-start justify-between flex-wrap gap-4"><div><div className="text-[10px] font-mono-tel uppercase tracking-[0.2em] text-slate-500">Module · 09 / Asset reliability</div><h1 className="font-display text-2xl md:text-3xl font-bold text-orange-100 mt-2">Equipment Maintenance</h1><p className="text-sm text-slate-400 mt-1">Predict failure risk from operating hours, service age, temperature, and vibration trends before equipment breaks.</p></div><Button onClick={() => toast.success("Equipment telemetry refreshed") } variant="outline" className="border-orange-500/40 text-orange-200"><Radio className="h-4 w-4 mr-2" />Refresh telemetry</Button></div>
      <section className="rounded-2xl border border-orange-500/25 bg-gradient-to-br from-orange-500/[.08] via-slate-950/70 to-slate-950/70 p-5 md:p-6"><div className="flex items-start gap-3"><div className="rounded-xl bg-orange-500/15 p-3"><Wrench className="h-6 w-6 text-orange-300" /></div><div><div className="text-[10px] font-mono-tel uppercase tracking-[.22em] text-orange-300">Predictive maintenance control layer</div><h2 className="font-display text-xl font-bold text-white mt-1">Warn command center before failure</h2><p className="text-sm text-slate-400 mt-1 max-w-3xl">POLARIS combines service age, utilization, temperature drift, and vibration drift into an explainable maintenance risk signal. It turns equipment telemetry into a scheduled action instead of an emergency report.</p></div></div><div className="grid grid-cols-2 lg:grid-cols-4 gap-3 mt-6"><Metric label="Assets monitored" value={assets.length} sub="Across 4 stations" icon={Gauge} tone="sky" /><Metric label="High risk" value={assets.filter(asset => asset.risk >= 60).length} sub="Needs action" icon={AlertTriangle} tone="rose" /><Metric label="Average risk" value={`${averageRisk}%`} sub="Fleet health signal" icon={TrendingUp} tone="amber" /><Metric label="Inspections due" value="2" sub="Within 72 hours" icon={CalendarClock} tone="orange" /></div></section>
      <section className="flex flex-wrap gap-3 items-center"><div className="relative flex-1 min-w-[220px] max-w-md"><Search className="absolute left-3 top-2.5 h-4 w-4 text-slate-500" /><input aria-label="Search equipment" value={query} onChange={event => setQuery(event.target.value)} placeholder="Search asset, type, or station" className="w-full rounded-lg border border-slate-700 bg-slate-950/80 py-2 pl-9 pr-3 text-sm text-slate-100 outline-none focus:border-orange-400" /></div><div className="w-52"><Select value={station} onValueChange={setStation}><SelectTrigger className="bg-slate-950/80 border-slate-700"><SelectValue /></SelectTrigger><SelectContent>{stations.map(item => <SelectItem key={item} value={item}>{item}</SelectItem>)}</SelectContent></Select></div><div className="w-44"><Select value={priority} onValueChange={setPriority}><SelectTrigger className="bg-slate-950/80 border-slate-700"><SelectValue /></SelectTrigger><SelectContent>{["All priorities", "HIGH", "MODERATE", "LOW"].map(item => <SelectItem key={item} value={item}>{item}</SelectItem>)}</SelectContent></Select></div></section>
      <section className="grid grid-cols-1 xl:grid-cols-[1.25fr_.75fr] gap-5"><div className="space-y-3">{filtered.map(asset => <AssetCard key={asset.id} asset={asset} selected={selectedId === asset.id} onSelect={() => setSelectedId(asset.id)} onInspect={() => inspection(asset)} />)}{!filtered.length && <div className="rounded-xl border border-slate-800 bg-slate-950/70 p-8 text-center text-slate-500">No equipment matches the selected filters.</div>}</div><div className="rounded-2xl border border-slate-800 bg-slate-950/70 p-5 h-fit sticky top-24"><div className="flex items-start justify-between gap-3"><div><div className="font-mono-tel text-[10px] uppercase tracking-widest text-orange-300">Asset detail</div><h2 className="font-display text-xl font-bold text-white mt-1">{selected.id}</h2><div className="text-xs text-slate-500 mt-1">{selected.type} · {selected.station}</div></div><Badge variant="outline" className={PRIORITY_STYLE[selected.priority]}>{selected.priority}</Badge></div><div className="mt-6 text-center rounded-xl border border-slate-800 bg-slate-950/70 p-5"><div className="font-mono-tel text-5xl font-bold text-rose-300">{selected.risk}%</div><div className="text-[10px] uppercase tracking-[.18em] text-slate-500 mt-2">predicted maintenance risk</div><Progress value={selected.risk} className="h-2 mt-4" /></div><div className="mt-5 space-y-3"><Detail icon={Gauge} label="Operating hours" value={`${selected.hours.toLocaleString()} h`} /><Detail icon={History} label="Last maintenance" value={`${selected.lastMaintenance} days ago`} /><Detail icon={Thermometer} label="Temperature trend" value={`↑ ${selected.temp}% signal`} tone="rose" /><Detail icon={TrendingUp} label="Vibration trend" value={`↑ ${selected.vibration}% signal`} tone="rose" /></div><div className="mt-5 rounded-lg border border-orange-500/25 bg-orange-500/[.05] p-3 text-xs text-slate-300 flex gap-2"><Clock3 className="h-4 w-4 text-orange-300 shrink-0" /><span>{selected.recommendation}</span></div><Button onClick={() => inspection(selected)} className="w-full mt-4 bg-orange-500 hover:bg-orange-400 text-slate-950"><CalendarClock className="h-4 w-4 mr-2" />Schedule inspection</Button><Button onClick={() => setShowHistory(value => !value)} variant="ghost" className="w-full mt-1 text-slate-400 hover:text-slate-200"><History className="h-4 w-4 mr-2" />{showHistory ? "Hide maintenance history" : "View maintenance history"}</Button>{showHistory && <div className="mt-3 border-t border-slate-800 pt-3 text-xs text-slate-400 space-y-2"><div className="flex justify-between"><span>Last service</span><span className="font-mono-tel text-slate-200">{selected.lastMaintenance || 0} days ago</span></div><div className="flex justify-between"><span>Telemetry model</span><span className="font-mono-tel text-emerald-300">v2.4 active</span></div><div className="flex justify-between"><span>Next review</span><span className="font-mono-tel text-orange-300">{selected.nextService}</span></div></div>}</div></section>
      <section className="rounded-2xl border border-slate-800 bg-slate-950/70 p-5"><div className="flex items-center gap-2"><ShieldCheck className="h-4 w-4 text-emerald-300" /><div><h2 className="font-display text-lg font-bold">How the prediction works</h2><p className="text-xs text-slate-500 mt-1">Transparent signals for command review — no black-box alerting.</p></div></div><div className="grid grid-cols-1 md:grid-cols-4 gap-3 mt-4">{[["Service age", "Days since last maintenance", History], ["Utilization", "Operating hours and duty cycle", Gauge], ["Temperature", "Rising thermal signal", Thermometer], ["Vibration", "Bearing / mechanical drift", TrendingUp]].map(([label, detail, Icon]) => <div key={label} className="rounded-lg border border-slate-800 p-3"><Icon className="h-4 w-4 text-orange-300" /><div className="text-sm font-semibold text-slate-200 mt-2">{label}</div><div className="text-[10px] text-slate-500 mt-1">{detail}</div></div>)}</div></section>
    </div>
  );
}
function AssetCard({ asset, selected, onSelect, onInspect }) { return <div onClick={onSelect} className={`rounded-xl border bg-slate-950/70 p-4 cursor-pointer transition-all hover:-translate-y-0.5 ${selected ? "border-orange-400/50 shadow-[0_12px_35px_rgba(249,115,22,.08)]" : "border-slate-800 hover:border-slate-700"}`}><div className="flex items-start justify-between gap-3"><div className="flex items-start gap-3"><div className={`h-10 w-10 rounded-lg grid place-items-center ${asset.risk >= 60 ? "bg-rose-500/15 text-rose-300" : asset.risk >= 35 ? "bg-amber-500/15 text-amber-300" : "bg-emerald-500/15 text-emerald-300"}`}><Zap className="h-5 w-5" /></div><div><div className="font-mono-tel text-xs text-slate-100">{asset.id}</div><div className="text-[11px] text-slate-500 mt-1">{asset.type} · {asset.station}</div></div></div><Badge variant="outline" className={PRIORITY_STYLE[asset.priority]}>{asset.priority}</Badge></div><div className="grid grid-cols-4 gap-2 mt-4"><Stat label="Risk" value={`${asset.risk}%`} tone={asset.risk >= 60 ? "text-rose-300" : asset.risk >= 35 ? "text-amber-300" : "text-emerald-300"} /><Stat label="Hours" value={asset.hours.toLocaleString()} /><Stat label="Temp" value={`↑ ${asset.temp}%`} /><Stat label="Vibration" value={`↑ ${asset.vibration}%`} /></div><div className="flex items-center justify-between mt-4 pt-3 border-t border-slate-800"><div className="text-xs text-slate-400">{asset.recommendation}</div>{asset.risk >= 60 && <Button onClick={event => { event.stopPropagation(); onInspect(); }} size="sm" variant="outline" className="shrink-0 border-orange-500/40 text-orange-200">Inspect</Button>}</div></div>; }
function Stat({ label, value, tone = "text-slate-200" }) { return <div><div className="text-[9px] uppercase tracking-widest text-slate-600">{label}</div><div className={`font-mono-tel text-sm mt-1 ${tone}`}>{value}</div></div>; }
function Detail({ icon: Icon, label, value, tone = "text-slate-200" }) { return <div className="flex items-center justify-between text-xs"><span className="flex items-center gap-2 text-slate-500"><Icon className="h-3.5 w-3.5 text-orange-300" />{label}</span><span className={`font-mono-tel ${tone}`}>{value}</span></div>; }
function Metric({ label, value, sub, icon: Icon, tone }) { const classes = { sky: "border-sky-500/25", rose: "border-rose-500/25", amber: "border-amber-500/25", orange: "border-orange-500/25" }; return <div className={`rounded-xl border ${classes[tone]} bg-slate-950/60 p-4`}><div className="flex justify-between"><div className="text-[10px] uppercase tracking-widest text-slate-500">{label}</div><Icon className="h-4 w-4 text-slate-500" /></div><div className="font-mono-tel text-2xl font-bold text-white mt-3">{value}</div><div className="text-[10px] text-slate-500 mt-1">{sub}</div></div>; }
